package demo; import net.fabricmc.loader.api.FabricLoader; import net.fabricmc.loader.api.ModContainer; import net.fabricmc.loader.api.metadata.*; public class Probe { static String v(CustomValue x){switch(x.getType()){case NUMBER:return "NUMBER";case STRING:return x.getAsString();case BOOLEAN:return Boolean.toString(x.getAsBoolean());case NULL:return "null";case OBJECT:{StringBuilder b=new StringBuilder("{");var i=x.getAsObject().iterator();while(i.hasNext()){var e=i.next();if(b.length()>1)b.append(',');b.append(e.getKey()).append('=').append(v(e.getValue()));}return b.append('}').toString();}case ARRAY:{StringBuilder b=new StringBuilder("[");var i=x.getAsArray().iterator();while(i.hasNext()){if(b.length()>1)b.append(',');b.append(v(i.next()));}return b.append(']').toString();}}throw new AssertionError();} public static String rows(CustomValue x){StringBuilder b=new StringBuilder();var o=x.getAsObject();var it=o.iterator();while(it.hasNext()){var e=it.next();b.append(e.getKey()).append('=').append(e.getValue().getType()).append(':').append(v(e.getValue())).append('|');}try{it.remove();}catch(Exception e){b.append("remove=").append(e.getClass().getName()).append('|');}return b.append("size=").append(o.size()).toString();} public static String numberText(){try{return FabricLoader.getInstance().getModContainer("demo").orElseThrow().getMetadata().getCustomValue("demo:cfg").getAsObject().get("zeta").getAsNumber().toString();}catch(NullPointerException e){return "npe";}} public static String rows(){return rows(FabricLoader.getInstance().getModContainer("demo").orElseThrow().getMetadata().getCustomValue("demo:cfg"));}}
